 $old=addSchedule($pdo,$agent,$slot);$pdo->prepare("UPDATE ".arc_table('network_agents')." SET agent_version='3.3.4' WHERE id=?")->execute([$agent['id']]);arc_support_schedules_dispatch($pdo,$agent);schCheck(runFor($pdo,$old)[0]['outcome']==='skipped','Old agent cannot execute scheduled jobs');
